	if _, err := cache.load(read); !errors.Is(err, failure) {
		t.Fatalf("second load returned %v, want %v", err, failure)
	}
	got, err := cache.load(read)
	if err != nil {
		t.Fatalf("third load: %v", err)
	}
	if len(got) != 1 {
		t.Fatalf("got %d mount points, want 1", len(got))
	}
	if _, err := cache.load(read); err != nil {
		t.Fatalf("fourth load: %v", err)
	}
	if *calls != 3 {
		t.Fatalf("read the mount table %d times, want 3", *calls)
	}
}

func TestMountTableCacheReadsOnceUnderConcurrency(t *testing.T) {
	t.Parallel()
	points := map[string]struct{}{"/": {}}
	read, calls := countingMountReader(points)
	cache := &mountTableCache{}

	var start, done sync.WaitGroup
	start.Add(1)
	for worker := 0; worker < 16; worker++ {
		done.Add(1)
		go func() {
			defer done.Done()
			start.Wait()
			if _, err := cache.load(read); err != nil {
				t.Errorf("load: %v", err)
			}
		}()
	}
	start.Done()
	done.Wait()

	if *calls != 1 {
		t.Fatalf("read the mount table %d times, want 1", *calls)
	}
}

// A new scope must not inherit the previous scope's snapshot: an operation that
// declares a boundary is asking for a table read before it resolves anything.
func TestMountTableScopeTakesAFreshSnapshot(t *testing.T) {
	t.Parallel()
	read, calls := countingMountReader(map[string]struct{}{"/": {}})

	first := &mountTableCache{}
	if _, err := first.load(read); err != nil {
		t.Fatalf("first scope load: %v", err)
	}
	second := &mountTableCache{}
	if _, err := second.load(read); err != nil {
		t.Fatalf("second scope load: %v", err)
	}
	if *calls != 2 {
		t.Fatalf("read the mount table %d times across two scopes, want 2", *calls)
	}
}

func TestBeginMountTableScopeReplacesTheActiveCache(t *testing.T) {
	before := activeMountTable.Load()
	beginMountTableScope()
	after := activeMountTable.Load()
	if after == before {
		t.Fatal("beginMountTableScope kept the previous cache")
	}
	if after == nil {
		t.Fatal("beginMountTableScope left no active cache")
	}
}
//go:build darwin || dragonfly || freebsd || openbsd

package sem

import (
	"errors"
	"path/filepath"
	"syscall"
)

const (
	bsdMountNowait       = 2
	maxBSDMountTableRows = 100_000
)

func newPathMountGuard(root, trustedBase string) (pathMountGuard, error) {
	mountPoints, err := cachedMountPoints(readBSDMountPoints)
	if err != nil {
		return pathMountGuard{}, err
	}
	return makePathMountGuard(root, trustedBase, mountPoints), nil
}

func readBSDMountPoints() (map[string]struct{}, error) {
	for attempt := 0; attempt < 3; attempt++ {
		count, err := syscall.Getfsstat(nil, bsdMountNowait)
		if err != nil {
			return nil, err
		}
		if count < 0 || count > maxBSDMountTableRows {
			return nil, errors.New("BSD mount table exceeded its row bound")
		}
		// Leave slack so a mount added between the sizing and snapshot calls
		// does not turn a silently truncated table into a permissive guard.
		rows := make([]syscall.Statfs_t, count+16)
		got, err := syscall.Getfsstat(rows, bsdMountNowait)
		if err != nil {
			return nil, err
		}
		if got < 0 || got > len(rows) {
			return nil, errors.New("invalid BSD mount table row count")
		}
		if got == len(rows) {
			continue
		}
		mounts := make(map[string]struct{}, got)
		for _, row := range rows[:got] {
			mount, terminated := bsdMountPath(bsdMountedOn(row))
			if !terminated || mount == "" || !filepath.IsAbs(mount) {
				return nil, errors.New("BSD mount table contained an invalid mount point")
			}
			mounts[filepath.Clean(mount)] = struct{}{}
		}
		return mounts, nil
	}
	return nil, errors.New("BSD mount table changed too quickly to snapshot")
}

func bsdMountPath(value []int8) (string, bool) {
	bytes := make([]byte, 0, len(value))
	for _, character := range value {
		if character == 0 {
			return string(bytes), true
		}
		bytes = append(bytes, byte(character))
	}
	return "", false
}
//go:build linux

