					ToID:          symbol.ID,
					Type:          "HANDLES_TOOL",
					Confidence:    0.85,
					Reason:        "tool boundary inferred from handler symbol body",
					RelationScope: "file",
					Resolution:    "pattern",
					TargetKind:    "symbol",
					Evidence: []Evidence{{
						Kind:      "symbol_body",
